// import zlib
//
// RAW = b"hello hello hello hello\n" * 3
// # zlib.compress(RAW) as produced by CPython: decoding it is build-independent.
// FIXTURE = b"x\x9c\xcbH\xcd\xc9\xc9W\xc8@'\xb90D\x08\x88\x03\x00\xc6\xb7\x1a/"
//
// main()
