    RAW = (::tpy::bytes_repeat(::tpy::bytes_literal_owned("hello hello hello hello\n", 24), 3));
    FIXTURE = ::tpy::bytes_literal_owned("x\x9c\xcbH\xcd\xc9\xc9W\xc8@'\xb9" "0D\x08\x88\x03\000\xc6\xb7\x1a/", 22);
